<?php
require_once 'config.php';require_login();expire_manual_requests();$uid=(int)$_SESSION['user_id'];
$s=db()->prepare('SELECT g.*,COUNT(DISTINCT gm2.user_id) members FROM group_members gm JOIN app_groups g ON g.id=gm.group_id LEFT JOIN group_members gm2 ON gm2.group_id=g.id WHERE gm.user_id=? GROUP BY g.id ORDER BY g.id DESC');$s->execute([$uid]);$groups=$s->fetchAll();
$s=db()->prepare("SELECT r.*,u.name FROM manual_requests r JOIN users u ON u.id=r.user_id WHERE r.user_id=? AND r.status='Failed' ORDER BY r.created_at DESC");$s->execute([$uid]);$failed=$s->fetchAll();$pageTitle='Group History';require 'header.php';?>
<h1>Group History</h1><h2>Your groups and members</h2><?php foreach($groups as $g):?><div class="card"><h3>Group-<?=$g['id']?> · <?=e($g['hostel_name'])?> · <?=e($g['app_name'])?></h3><p>Status: <b><?=e($g['status'])?></b> · <?= (int)$g['members']?> members · Target ₹<?=e(number_format((float)$g['target_threshold'],2))?></p><p><b>Members:</b> <?php $m=db()->prepare('SELECT u.name,u.roll_no FROM group_members gm JOIN users u ON u.id=gm.user_id WHERE gm.group_id=? ORDER BY u.name');$m->execute([$g['id']]);echo e(implode(', ',array_map(fn($x)=>$x['name'].' ('.$x['roll_no'].')',$m->fetchAll())));?></p><a href="group.php?id=<?=(int)$g['id']?>">View full group history →</a></div><?php endforeach;if(!$groups):?><div class="card">Abhi tak koi group history nahi hai.</div><?php endif;?>
<h2>Failed listings</h2><?php foreach($failed as $r):?><div class="card"><h3><badge>Failed</badge> <?=e($r['hostel_name'])?> · <?=e($r['app_name'])?></h3><p>Threshold ₹<?=e(number_format((float)$r['threshold_value'],2))?> · Purchase ₹<?=e(number_format((float)$r['purchase_amount'],2))?></p><p>Expiry: <?=e($r['expires_at'])?></p></div><?php endforeach;if(!$failed):?><div class="card">Koi failed listing nahi hai.</div><?php endif;?><?php require 'footer.php';?>
